from fastapi.responses import JSONResponse
from fastapi.exceptions import HTTPException
import json
import logging
from typing import Dict
import time
from datetime import datetime, timedelta

# Initialize the logger
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Initialize the mock user database
users: Dict[int, Dict[str, str]] = {
    1: {"name": "John Doe", "email": "john@example.com"},
    2: {"name": "Jane Doe", "email": "jane@example.com"},
}

# Initialize the cache
cache: Dict[str, str] = {}

app = FastAPI()

# Cache decorator with TTL
def cache_control(ttl: int):
    def decorator(func):
        def wrapper(*args, **kwargs):
            cache_key = json.dumps(args) + json.dumps(kwargs)
            if cache_key in cache:
                timestamp = json.loads(cache[cache_key].split("|")[1])
                if datetime.now() - timedelta(seconds=ttl) <= datetime.fromtimestamp(timestamp):
                    return json.loads(cache[cache_key].split("|")[0])
            result = func(*args, **kwargs)
            cache[cache_key] = json.dumps((result, int(time.time())))
            return result
        return wrapper
    return decorator

# Update user in the database
def update_user(user_id: int, new_data: Dict[str, str]):
    global users
    if user_id in users:
        users[user_id].update(new_data)
        # Invalidate the cache for the updated user
        cache.pop(json.dumps((user_id,)), None)

# Get user from the database
def get_user(user_id: int):
    global users
    if user_id in users:
        return users[user_id]
    else:
        raise HTTPException(status_code=404, detail="User not found")

