from apscheduler.schedulers.asyncio import AsyncIOScheduler
from datetime import datetime
import logging
import logging.config

# Configure logging
logging.config.dictConfig({
    'version': 1,
    'formatters': {
        'default': {
            'format': '[%(asctime)s] %(levelname)s in %(module)s: %(message)s',
        }
    },
    'handlers': {
        'default': {
            'class': 'logging.StreamHandler',
            'formatter': 'default',
        }
    },
    'root': {
        'level': 'INFO',
        'handlers': ['default']
    }
})

# Initialize FastAPI application
app = FastAPI()

# Initialize APScheduler
scheduler = AsyncIOScheduler()

# In-memory task store
tasks = []

# Cleanup task that runs every 60 seconds to clean up completed tasks
def cleanup_task():
    global tasks
    tasks = [task for task in tasks if task['status'] != 'completed']

# Create a new task with a given name and interval (in seconds)
@app.post("/tasks")
async def create_task(name: str, interval: int):
    global tasks
    try:
        # Add task to the in-memory store
        task = {'id': len(tasks) + 1, 'name': name, 'interval': interval, 'status': 'pending', 'next_execution': datetime.now()}
        tasks.append(task)
        # Schedule the task with APScheduler
        scheduler.add_job(log_task, 'interval', seconds=interval, id=task['id'], name=name, replace_existing=True)
        # Start the scheduler if it's not already running
        if not scheduler.running:
            scheduler.start()
        return {'task_id': task['id']}
    except Exception as e:
        logging.error(f"Failed to create task: {str(e)}")
        raise HTTPException(status_code=500, detail="Failed to create task")

# Log a message to the console with the task name
async def log_task(task):
    try:
        global tasks
        task_id = task.id
        task_name = task.name
        logging.info(f"Task {task_id} ({task_name}) executed")
        # Update the task status in the in-memory store
        tasks = [t for t in tasks if t['id'] != task_id]
        tasks.append({'id': task_id, 'name': task_name, 'interval': task.interval, 'status': 'completed', 'next_execution': task.next_run_time})
    except Exception as e:
        logging.error(f"Failed to execute task {task_id} ({task_name}): {str(e)}")

# Return a list of all scheduled tasks, including their IDs, names, and next execution times
@app.get("/tasks")
async def get_tasks():
    global tasks
    try:
        return [{'id': task['id'], 'name': task['name'], 'next_execution': task['next_execution']} for task in tasks]
    except Exception as e:
        logging.error(f"Failed to get tasks: {str(e)}")
        raise HTTPException(status_code=500, detail="Failed to get tasks")

# Return the details of a specific task by ID
@app.get("/tasks/{task_id}")
async def get_task(task_id: int):
    global tasks
    try:
        task = next((task for task in tasks if task['id'] == task_id), None)
        if task:
            return {'id': task['id'], 'name': task['name'], 'interval': task['interval'], 'status': task['status'], 'next_execution': task['next_execution']}
        else:
            raise HTTPException(status_code=404, detail="Task not found")
    except Exception as e:
        logging.error(f"Failed to get task {task_id}: {str(e)}")
        raise HTTPException(status_code=500, detail="Failed to get task")

# Cancel a scheduled task by ID
@app.delete("/tasks/{task_id}")
async def delete_task(task_id: int):
    global tasks
    try:
        task = next((task for task in tasks if task['id'] == task_id), None)
        if task:
            # Remove the task from APScheduler
            scheduler.remove_job(task_id)
            # Remove the task from the in-memory store
            tasks = [t for t in tasks if t['id'] != task_id]
            return {'task_id': task_id}
        else:
            raise HTTPException(status_code=404, detail="Task not found")
    except Exception as e:
        logging.error(f"Failed to delete task {task_id}: {str(e)}")
        raise HTTPException(status_code=500, detail="Failed to delete task")

