import asyncio
import uvicorn

app = FastAPI()

templates = Jinja2Templates(directory="templates")

class User(BaseModel):
    id: str
    name: str

connected_users: Dict[str, User] = {}

@app.get("/")
async def get_index(request: Request):
    return templates.TemplateResponse("index.html", {"request": request})

@app.get("/ws")
async def websocket_endpoint(websocket: WebSocket):
    await websocket.accept()

    while True:
        message = await websocket.receive_text()
        broadcast_message(message, websocket)

        if message == "/quit":
            break

    connected_users.pop(websocket.client_id, None)
    await websocket.close()

@app.get("/users")
async def get_users():
    return {"users": connected_users.values()}

async def broadcast_message(message: str, sender: WebSocket):
    for user, ws in connected_users.items():
        if user != sender.client_id:
            await ws.send_text(f"{sender.name}: {message}")

async def send_pings():
    while True:
        for user, ws in connected_users.copy().items():
            try:
                await ws.send_text("ping")
            except Exception as e:
                print(f"Error sending ping to {user}: {e}")
                connected_users.pop(user, None)
        await asyncio.sleep(10)

background_task = asyncio.create_task(send_pings())

if __name__ == "__main__":
    uvicorn.run(app, host="0.0.0.0", port=8000)
