# Set the maximum number of worker threads and processes
MAX_THREADS = 5
MAX_PROCESSES = 5

# Define a function to send an HTTP GET request to a URL
def send_request(url: str) -> str:
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()  # Raise an exception for HTTP errors
        return response.text
    except requests.RequestException as e:
        print(f"Error sending request to {url}: {e}")
        return None

# Define a function to parse HTML content using BeautifulSoup
def parse_html(html: str) -> str:
    try:
        soup = BeautifulSoup(html, 'html.parser')
        return soup.prettify()
    except Exception as e:
        print(f"Error parsing HTML: {e}")
        return None

# Define a function to handle downloading and parsing a single URL
def handle_url(url: str) -> Dict[str, str]:
    start_time = time.time()
    html = send_request(url)
    if html is None:
        return {url: "Failed to download"}

    parsed_html = parse_html(html)
    if parsed_html is None:
        return {url: "Failed to parse"}

    end_time = time.time()
    print(f"Downloaded and parsed {url} in {end_time - start_time:.2f} seconds")
    return {url: parsed_html}

# Define a function to concurrently download multiple URLs
def concurrent_download(urls: List[str]) -> Dict[str, str]:
    with concurrent.futures.ThreadPoolExecutor(max_workers=MAX_THREADS) as executor:
        futures = {executor.submit(handle_url, url): url for url in urls}
        results = {}
        for future in concurrent.futures.as_completed(futures):
            url = futures[future]
            try:
                result = future.result()
                results[url] = result[url]
            except Exception as e:
                print(f"Error handling {url}: {e}")
        return results

# Define a function to parallelize the parsing of HTML content using multiprocessing
def parallel_parse(htmls: Dict[str, str]) -> Dict[str, str]:
    with concurrent.futures.ProcessPoolExecutor(max_workers=MAX_PROCESSES) as executor:
        futures = {executor.submit(partial(parse_html, html)): url for url, html in htmls.items()}
        results = {}
        for future in concurrent.futures.as_completed(futures):
            url = futures[future]
            try:
                result = future.result()
                results[url] = result
            except Exception as e:
                print(f"Error parsing {url}: {e}")
        return results

