from fastapi import FastAPI, HTTPException
from fastapi.responses import JSONResponse
from pydantic import BaseModel
from typing import List
from asyncpg import Pool, DatabaseError

app = FastAPI()

class User(BaseModel):
    id: int
    username: str
    email: str
    posts: List[dict]

class Post(BaseModel):
    id: int
    title: str
    content: str

@app.on_event("shutdown")
async def shutdown_event():
    await pool.close()

@app.get("/users", response_model=List[User])
async def get_users(offset: int = 0, limit: int = 10):
    try:
        query = """
            SELECT u.id, u.username, u.email, p.id AS post_id, p.title, p.content
            FROM users u
            LEFT JOIN posts p ON u.id = p.user_id
            ORDER BY u.id
            OFFSET $1
            LIMIT $2
        """
        result = await pool.fetch(query, offset, limit)
        users = []
        for row in result:
            user = User(
                id=row["id"],
                username=row["username"],
                email=row["email"],
                posts=[
                    Post(id=row["post_id"], title=row["title"], content=row["content"])
                    for row in result
                    if row["user_id"] == row["id"]
                ]
            )
            users.append(user)
        return users
    except DatabaseError as e:
        raise HTTPException(status_code=500, detail=str(e))
