from redis import Redis
from redis.commands.pipeline import Pipeline
from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker

app = FastAPI()

# Redis connection settings
redis_host = 'localhost'
redis_port = 6379

# PostgreSQL database connection settings
database_url = 'postgresql://user:password@localhost/database'

# Create a Redis connection
redis_client = Redis(host=redis_host, port=redis_port)

# Create a PostgreSQL database engine
engine = create_engine(database_url)

# Create a session maker
SessionLocal = sessionmaker(bind=engine)

# Define a Pydantic model for the book
class BookModel(BaseModel):
    id: int
    title: str
    author: str
    publication_year: int

# Define a Pydantic model for the book list
class BookListModel(BaseModel):
    books: List[BookModel]

# Define a FastAPI endpoint to retrieve the list of books from the database and cache the result in Redis for 5 minutes
@app.get("/books", response_model=BookListModel)
def get_books():
    # Get a database session
    db = SessionLocal()
    try:
        # Retrieve the list of books from the database
        books = db.query(Book).all()
        # Cache the result in Redis for 5 minutes
        redis_client.expire("books", 300)
        redis_client.set("books", books)
        # Return the cached result
        return BookListModel(books=[BookModel(id=b.id, title=b.title, author=b.author, publication_year=b.publication_year) for b in books])
    finally:
        # Close the database session
        db.close()

# Define a FastAPI endpoint to add a new book to the database and update the cached list of books in Redis
@app.post("/books")
def add_book(book: BookModel):
    # Get a database session
    db = SessionLocal()
    try:
        # Create a new book instance
        new_book = Book(title=book.title, author=book.author, publication_year=book.publication_year)
        # Add the new book to the database
        db.add(new_book)
        # Commit the changes to the database
        db.commit()
        # Update the cached list of books in Redis
        books = db.query(Book).all()
        redis_client.set("books", books)
        redis_client.expire("books", 300)
        # Return the updated list of books
        return BookListModel(books=[BookModel(id=b.id, title=b.title, author=b.author, publication_year=b.publication_year) for b in books])
    finally:
        # Close the database session
        db.close()
