Create a function `loadComponent` to load components dynamically using Webpack's `import()` function.

```typescript
import { Suspense, useEffect, useState } from 'react';

const loadComponent = async (componentPath: string) => {
  const component = await import(componentPath);
  return component.default;
};

const LazyComponent: React.FC<{ path: string }> = ({ path }) => {
  const [component, setComponent] = useState<React.FC | null>(null);
  useEffect(() => {
    const load = async () => {
      const loadedComponent = await loadComponent(path);
      setComponent(loadedComponent);
    };
    load();
  }, [path]);

  if (!component) {
    return <div>Loading...</div>;
  }

  return (
    <Suspense fallback={<div>Loading...</div>}>
      <component />
    </Suspense>
  );
};

export default LazyComponent;
