            setSensorReadings(readings);
        };
        return () => {
            eventSource.close();
        };
    }, []);

    useEffect(() => {
        const webSocket = new WebSocket("ws://localhost:8000/ws");
        webSocket.onmessage = event => {
            const message = JSON.parse(event.data);
            if (message.sensor === selectedSensor) {
                setSensorReadings({ ...sensorReadings, [selectedSensor]: message.value });
            }
        };
        webSocket.onclose = () => {
            console.log("WebSocket closed");
        };
        return () => {
            webSocket.close();
        };
    }, [selectedSensor]);

    const handleSensorChange = event => {
        setSelectedSensor(event.target.value);
    };

    return (
        <div>
            <h1>Sensor Readings</h1>
            <select value={selectedSensor} onChange={handleSensorChange}>
                {sensors.map(sensor => (
                    <option key={sensor} value={sensor}>
                        {sensor}
                    </option>
                ))}
            </select>
            <ul>
                {Object.keys(sensorReadings).map(sensor => (
                    <li key={sensor}>
                        <strong>{sensor}</strong>: {sensorReadings[sensor]}
                    </li>
                ))}
            </ul>
        </div>
    );
}

export default Dashboard;
```

**Explanation and Example Use Cases**

The FastAPI backend generates random sensor readings every 2 seconds and broadcasts them to connected clients using SSE. The WebSocket endpoint handles client connections and sends updates when a user toggles between sensors.

The React frontend displays the live feed of sensor readings and allows users to toggle between sensors. When a user selects a sensor, the frontend sends a WebSocket message to the backend, which updates the sensor reading and sends the new value back to the frontend.

Example use cases:

* User selects the "temperature" sensor and sees the current reading.
* User toggles to the "humidity" sensor and sees the current reading.
* User selects a different sensor and sees the new reading.
* User closes the browser tab and the WebSocket connection is closed.

