### Implementation

#### 1. `useAuth.js` Hook

This hook manages the authentication state and provides methods to interact with the OAuth 2.0 server.
```jsx
// src/hooks/useAuth.js
import { useState, useEffect } from 'react';
import { useHistory } from 'react-router-dom';
import { storage } from './storage';

const clientId = 'your_client_id';
const clientSecret = 'your_client_secret';
const tokenEndpoint = 'https://example.com/oauth/token';
const redirectUri = 'http://localhost:3000/callback';
const scopes = ['profile', 'email'];

const useAuth = () => {
  const [authState, setAuthState] = useState({
    loading: false,
    error: null,
    user: null,
  });
  const history = useHistory();

  const login = async () => {
    const codeVerifier = crypto.randomUUID();
    const codeChallenge = crypto.createHash('sha256').update(codeVerifier).digest('base64');
    const authUrl = `https://example.com/oauth/authorize?client_id=${clientId}&redirect_uri=${redirectUri}&response_type=code&scope=${scopes.join('%20')}&code_challenge=${codeChallenge}&code_challenge_method=S256`;

    history.push(authUrl);
  };

  const handleCallback = async (code) => {
    try {
      const response = await axios.post(tokenEndpoint, {
        grant_type: 'authorization_code',
        code,
        redirect_uri: redirectUri,
        client_id: clientId,
        client_secret: clientSecret,
      });

      storage.setAccessToken(response.data.access_token);
      storage.setRefreshToken(response.data.refresh_token);

      const refreshToken = await storage.getRefreshToken();
      const accessToken = await storage.getAccessToken();

      if (refreshToken && accessToken) {
        const user = await fetchUser(accessToken);
        setAuthState({ loading: false, error: null, user });
      }
    } catch (error) {
      setAuthState({ loading: false, error });
    }
  };

  const logout = async () => {
    try {
      await axios.post(tokenEndpoint, {
        grant_type: 'revocation',
        token: storage.getAccessToken(),
      });

      storage.removeAccessToken();
      storage.removeRefreshToken();
      setAuthState({ loading: false, error: null, user: null });
    } catch (error) {
      setAuthState({ loading: false, error });
    }
  };

  const isAuth = () => {
    const accessToken = storage.getAccessToken();
    return accessToken !== null;
  };

  return {
    authState,
    login,
    handleCallback,
    logout,
    isAuth,
  };
};

export default useAuth;
```

