from fastapi import FastAPI
from fastapi.responses import JSONResponse
from fastapi_ws import WebSocketManager
from fastapi import WebSocket

app = FastAPI()
ws_manager = WebSocketManager(app)

# Initialize a set to store connected clients
connected_clients = set()

@app.websocket("/ws")
async def websocket_endpoint(websocket: WebSocket):
    await websocket.accept()
    connected_clients.add(websocket)
    await websocket.send_json({"type": "connection", "message": "Connected to the chat"})

    try:
        while True:
            message = await websocket.receive_json()
            if message["type"] == "message":
                await broadcast_message(message["content"])
            elif message["type"] == "disconnect":
                connected_clients.remove(websocket)
                await websocket.send_json({"type": "connection", "message": "Disconnected from the chat"})
                break
    except WebSocketDisconnect:
        connected_clients.remove(websocket)
        await websocket.send_json({"type": "connection", "message": "Disconnected from the chat"})

async def broadcast_message(message):
    for client in connected_clients:
        await client.send_json({"type": "message", "content": message})
