// image-worker.js
import { Worker } from 'worker_threads';

class ImageWorker {
  constructor(imageData, filter) {
    this.imageData = imageData;
    this.filter = filter;
  }

  processImage() {
    const { thread } = this;
    return new Promise((resolve, reject) => {
      thread.postMessage({ action: 'processImage', filter: this.filter });
      thread.on('message', (data) => {
        if (data.action === 'imageProcessed') {
          resolve(data.imageData);
        } else if (data.action === 'error') {
          reject(data.error);
        }
      });
    });
  }
}

export default ImageWorker;
```

This Web Worker class takes the image data and filter as inputs and returns a promise that resolves with the processed image data.

