# Define the user feedback model
class UserFeedback(BaseModel):
    name: str
    email: str
    feedback: str

# Define the route to handle user feedback submissions
@app.post("/feedback")
async def submit_feedback(feedback: UserFeedback):
    try:
        # Validate the user input
        feedback = UserFeedback.parse_obj(feedback)

        # Store the feedback in the MongoDB database
        await db["feedback"].insert_one(feedback.dict())
        return JSONResponse(status_code=201, content={"message": "Feedback submitted successfully"})
    except motor.errors.OperationFailure as e:
        # Log the error and return an error response
        logger.error(f"Error storing feedback: {e}")
        raise HTTPException(status_code=500, detail="Error storing feedback")
    except Exception as e:
        # Log the error and return an error response
        logger.error(f"Unexpected error: {e}")
        raise HTTPException(status_code=500, detail="Unexpected error")

# Define a custom exception handler
async def catch_all_exceptions(request, exc):
    # Log the error and return an error response
    logger.error(f"Error handling request: {exc}")
    return JSONResponse(status_code=500, content={"message": "Internal Server Error"})

# Add the custom exception handler
@app.exception_handler(Exception)
async def handle_exception(request, exc):
    return await catch_all_exceptions(request, exc)
