// src/store/reducers/todoReducer.js
import { TodoState } from '../types';

const initialState: TodoState = {
  todoList: [],
  completedList: [],
};

const todoReducer = (state = initialState, action) => {
  switch (action.type) {
    case 'ADD_TODO':
      return {
        ...state,
        todoList: [...state.todoList, action.payload],
      };
    case 'DELETE_TODO':
      return {
        ...state,
        todoList: state.todoList.filter((todo) => todo.id !== action.payload.id),
      };
    case 'UPDATE_TODO':
      return {
        ...state,
        todoList: state.todoList.map((todo) =>
          todo.id === action.payload.id ? action.payload : todo
        ),
      };
    case 'COMPLETE_TODO':
      return {
        ...state,
        todoList: state.todoList.map((todo) =>
          todo.id === action.payload.id ? { ...todo, completed: true } : todo
        ),
        completedList: [...state.completedList, action.payload],
      };
    case 'UNCOMPLETE_TODO':
      return {
        ...state,
        todoList: state.todoList.map((todo) =>
          todo.id === action.payload.id ? { ...todo, completed: false } : todo
        ),
        completedList: state.completedList.filter(
          (completedTodo) => completedTodo.id !== action.payload.id
        ),
      };
    default:
      return state;
  }
};

export default todoReducer;
```

